generate.initial_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investor ?investorName ?score
WHERE {
  # Net cash flow per investor
  {
    SELECT ?investor (SUM(xsd:decimal(?cfAmt)) AS ?netCashFlow)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:cashFlowOfInvestor ?investor ;
          wm:amount ?cfAmt .
    }
    GROUP BY ?investor
  }
  # Holding gain per investor (currentValue - cost)
  {
    SELECT ?investor (SUM(xsd:decimal(?gain)) AS ?holdingGain)
    WHERE {
      ?ph a wm:PortfolioHolding ;
          wm:heldByInvestor ?investor ;
          wm:currentValue ?cv ;
          wm:cost ?cost .
      BIND (xsd:decimal(?cv) - xsd:decimal(?cost) AS ?gain)
    }
    GROUP BY ?investor
  }
  # Average shortfall per investor
  {
    SELECT ?investor (AVG(xsd:decimal(?shortfall)) AS ?avgShortfall)
    WHERE {
      ?ig a wm:InvestmentGoal ;
          wm:belongsToInvestor ?investor ;
          wm:shortfall ?shortfall .
    }
    GROUP BY ?investor
  }
  # Rebalance amount per investor
  {
    SELECT ?investor (SUM(xsd:decimal(?raAmt)) AS ?rebalanceAmt)
    WHERE {
      ?ra a wm:RebalancingAction ;
          wm:rebalancingActionOfInvestor ?investor ;
          wm:amount ?raAmt .
    }
    GROUP BY ?investor
  }
  # Investor name
  OPTIONAL { ?investor wm:investorName ?investorName . }

  # Compute composite score
  BIND ( COALESCE(?netCashFlow, 0) + COALESCE(?holdingGain, 0) - COALESCE(?avgShortfall, 0) + COALESCE(?rebalanceAmt, 0) AS ?score )
}
ORDER BY DESC(?score)
LIMIT 10

